function fetchWithTimeout(url, options = {}) {
  return fetch(url, { ...options, signal: AbortSignal.timeout(FETCH_TIMEOUT_MS) });
}
async function readJson(response) {
  const text = await response.text();
  if (!text) return {};
  try { return JSON.parse(text); } catch { return {}; }
}
function decodeResult(value) {
  let current = value;
  for (let i = 0; i < 3; i += 1) {
    if (Array.isArray(current) && current.length === 1) current = current[0];
    if (typeof current === "string") { try { current = JSON.parse(current); continue; } catch { break; } }
    if (current && typeof current === "object" && "data" in current) { current = current.data; continue; }
    break;
  }
  return current && typeof current === "object" ? current : {};
}
function bodyOf(request) {
  const contentType = String(request.headers["content-type"] || "").toLowerCase();
  if (contentType && !contentType.includes("application/json")) throw Object.assign(new Error("BAD_TYPE"), { statusCode: 415 });
  const length = Number(request.headers["content-length"] || 0);
  if (Number.isFinite(length) && length > MAX_BODY_BYTES) throw Object.assign(new Error("TOO_LARGE"), { statusCode: 413 });
  if (!request.body) return {};
  if (typeof request.body === "string") {
    if (Buffer.byteLength(request.body, "utf8") > MAX_BODY_BYTES) throw Object.assign(new Error("TOO_LARGE"), { statusCode: 413 });
    try { return JSON.parse(request.body); } catch { throw Object.assign(new Error("BAD_JSON"), { statusCode: 400 }); }
  }
  if (typeof request.body !== "object" || Array.isArray(request.body)) throw Object.assign(new Error("BAD_JSON"), { statusCode: 400 });
  return request.body;
}
function consumeRateLimit(request, token) {
  const forwarded = String(request.headers["x-vercel-forwarded-for"] || request.headers["x-forwarded-for"] || "");
  const ip = forwarded.split(",")[0].trim().slice(0,80) || "unknown";
  const hash = createHash("sha256").update(token).digest("base64url").slice(0,24);
  const key = ip + ":" + hash;
  const now = Date.now();
  if (rateLimitBuckets.size > 5000) { for (const [k,v] of rateLimitBuckets) if (!v || v.resetAt <= now) rateLimitBuckets.delete(k); }
  let bucket = rateLimitBuckets.get(key);
  if (!bucket || bucket.resetAt <= now) bucket = { count: 0, resetAt: now + RATE_LIMIT_WINDOW_MS };
  bucket.count += 1; rateLimitBuckets.set(key,bucket);
  return { allowed: bucket.count <= RATE_LIMIT_MAX_REQUESTS, remaining: Math.max(0,RATE_LIMIT_MAX_REQUESTS-bucket.count), retryAfter: Math.max(1,Math.ceil((bucket.resetAt-now)/1000)) };
}
async function activeSubscription(url, key, token) {
  const response = await fetchWithTimeout(url + "/rest/v1/rpc/nexora_my_subscription_status_v264", {
    method: "POST",
    headers: { apikey: key, Authorization: "Bearer " + token, "Content-Type": "application/json" },
    body: JSON.stringify({ p_product_code: "eleves" })
  });
  if (!response.ok) throw new Error("SUBSCRIPTION_CHECK_FAILED");
  const data = decodeResult(await readJson(response));
  const now = Date.parse(data.server_now || "") || Date.now();
  const end = Date.parse(data.ends_at || "") || 0;
  return data.active === true && String(data.status || "") === "active" && end > now;
}

export default async function handler(request, response) {
  response.setHeader("Cache-Control", "private, no-store, max-age=0, must-revalidate");
  response.setHeader("Pragma", "no-cache");
  response.setHeader("Expires", "0");
  response.setHeader("Content-Type", "application/json; charset=utf-8");
  response.setHeader("Vary", "Authorization");
  response.setHeader("X-Content-Type-Options", "nosniff");
  if (request.method !== "POST") { response.setHeader("Allow","POST"); return response.status(405).json({success:false,message:"Méthode refusée."}); }
  try {
    const authorization = String(request.headers.authorization || "");
    const token = authorization.startsWith("Bearer ") ? authorization.slice(7).trim() : "";
    if (!token || token.length > 10000) return response.status(401).json({success:false,message:"Connexion Nexora obligatoire."});
    const limit = consumeRateLimit(request,token);
    response.setHeader("X-RateLimit-Limit",String(RATE_LIMIT_MAX_REQUESTS));
    response.setHeader("X-RateLimit-Remaining",String(limit.remaining));
    if (!limit.allowed) { response.setHeader("Retry-After",String(limit.retryAfter)); return response.status(429).json({success:false,message:"Trop de demandes rapprochées."}); }
    const body = bodyOf(request);
    const kind = String(body.kind || "");
    if (kind !== "novels" && kind !== "subjects") return response.status(400).json({success:false,message:"Rubrique premium invalide."});
    const url = String(process.env.SUPABASE_URL || DEFAULT_SUPABASE_URL).replace(/\/$/,"");
    const key = String(process.env.SUPABASE_PUBLISHABLE_KEY || DEFAULT_PUBLISHABLE_KEY);
    const userResponse = await fetchWithTimeout(url + "/auth/v1/user", { headers: { apikey:key, Authorization:"Bearer "+token } });
    if (!userResponse.ok) return response.status(401).json({success:false,message:"Session Nexora invalide ou expirée."});
    const user = await readJson(userResponse);
    if (!user || !user.id) return response.status(401).json({success:false,message:"Compte Nexora introuvable."});
    if (!(await activeSubscription(url,key,token))) return response.status(403).json({success:false,message:"Un abonnement Nexora actif est nécessaire pour cette rubrique."});
    const items = kind === "novels" ? NOVELS : EXAM_SUBJECTS;
    return response.status(200).json({success:true,kind,items});
  } catch (error) {
    if (error && error.statusCode) return response.status(error.statusCode).json({success:false,message:error.statusCode===413?"Demande trop volumineuse.":(error.statusCode===415?"Format JSON obligatoire.":"Demande invalide.")});
    console.error("Nexora premium-library", error && error.message ? error.message : error);
    return response.status(503).json({success:false,message:"Vérification de l’abonnement momentanément indisponible."});
  }
}
